function chooseImageColor(e){if(!picking||loading||exporting||aiRunning||(e.type==='pointerdown'&&e.button!==0))return;const bounds=$('preview').getBoundingClientRect(),x=Math.min(previewSource.width-1,Math.max(0,Math.floor((e.clientX-bounds.left)/bounds.width*previewSource.width))),y=Math.min(previewSource.height-1,Math.max(0,Math.floor((e.clientY-bounds.top)/bounds.height*previewSource.height)));const px=previewSource.getContext('2d').getImageData(x,y,1,1).data;if(px[3]===0){status('Ese p\xEDxel ya es transparente. Elige una zona visible.',true);return;}const color='#'+[...px.slice(0,3)].map(n=>n.toString(16).padStart(2,'0')).join('');if(picking==='remove'){$('removeColor').value=color;$('removeOn').checked=true;}else if(picking==='halftone'){$('halftoneColor').value=color;$('halftoneMode').value='color';$('halftoneOn').checked=true;}else{$('fromColor').value=color;$('recolorOn').checked=true;}picking=null;originalView=false;document.body.classList.remove('picking');historyCommit();schedule();if(window.matchMedia?.('(max-width:700px)')?.matches)document.querySelector('.lz-mobile-switch [data-pane="controls"]')?.click();}
$('preview').addEventListener('pointerdown',chooseImageColor);$('preview').addEventListener('click',chooseImageColor);
$('background').onchange=()=>{const b=$('background').value;$('previewStage').classList.toggle('checker',b==='transparent');$('previewStage').style.backgroundColor=b==='transparent'?'':b;$('previewStage').style.backgroundImage=b==='transparent'?'':'none';};
$('zoomIn').onclick=()=>{fitView=false;zoom=Math.min(4,zoom*1.35);layout();};$('zoomOut').onclick=()=>{fitView=false;zoom=Math.max(.03,zoom/1.35);layout();};$('fit').onclick=()=>{fitView=true;layout();};new ResizeObserver(()=>{if(fitView)layout();}).observe(document.querySelector('.preview-wrap'));
