const previewStage=$('previewStage');previewStage.addEventListener('wheel',event=>{if(!previewSource)return;event.preventDefault();fitView=false;const factor=event.deltaY<0?1.14:1/1.14;zoom=Math.max(.03,Math.min(4,zoom*factor));layout();},{passive:false});
const uploadTarget=document.querySelector('label.upload[for="file"]');let uploadHovered=false;uploadTarget.addEventListener('pointerenter',()=>{uploadHovered=true;uploadTarget.classList.add('paste-ready');});uploadTarget.addEventListener('pointerleave',()=>{uploadHovered=false;uploadTarget.classList.remove('paste-ready');});document.addEventListener('paste',event=>{if(!uploadHovered)return;const item=[...(event.clipboardData?.items||[])].find(entry=>entry.type.startsWith('image/'));if(!item)return;event.preventDefault();const file=item.getAsFile();if(file){upload(file);status('Imagen pegada desde el portapapeles.');}});
function toggleMenu(open){$('moduleMenu').hidden=!open;$('menuBackdrop').hidden=!open;$('menuButton').setAttribute('aria-expanded',String(open));if(open)$('menuClose').focus();}
$('menuButton').onclick=()=>toggleMenu($('moduleMenu').hidden);$('menuClose').onclick=()=>toggleMenu(false);$('menuBackdrop').onclick=()=>toggleMenu(false);$('moduleMenu').addEventListener('click',event=>{const link=event.target.closest('a');if(link?.getAttribute('href')===editorRoute){event.preventDefault();toggleMenu(false);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(picking){picking=null;document.body.classList.remove('picking');status('Selecci\xF3n de color cancelada.');}else if(!$('moduleMenu').hidden)toggleMenu(false);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('undo').click();}});$('exportDialog').addEventListener('cancel',e=>e.preventDefault());
const drop=document.querySelector('.preview-wrap');for(const ev of ['dragenter','dragover'])drop.addEventListener(ev,e=>{e.preventDefault();drop.style.outline='2px solid #727579';});drop.addEventListener('dragleave',()=>drop.style.outline='');drop.addEventListener('drop',e=>{e.preventDefault();drop.style.outline='';upload(e.dataTransfer.files[0]);});
